head.b:skin:
/*
-----------------------------------------------
Blogger Template Style
Name:     Murdock Emisembe Foundation
Version:  2.0.0
Notes:    Rebuilt from the foundation's previous template. Dependency-free.
----------------------------------------------- */

/* Variable definitions (editable in Theme > Customise > Advanced)
====================
<Variable name="primary.color" description="Primary blue (header text, buttons, footer)" type="color" default="#145474" value="#145474"/>
<Variable name="primary.deep.color" description="Deep blue (footer, dark sections)" type="color" default="#0B3349" value="#0B3349"/>
<Variable name="accent.color" description="Accent green (Donate button, highlights)" type="color" default="#87BA45" value="#87BA45"/>
<Variable name="accent.deep.color" description="Dark green (green text on white)" type="color" default="#4A7A1C" value="#4A7A1C"/>
<Variable name="sand.color" description="Warm background for alternating sections" type="color" default="#F6EEE3" value="#F6EEE3"/>
<Variable name="text.color" description="Body text" type="color" default="#2E3D47" value="#2E3D47"/>
<Variable name="heading.color" description="Headings" type="color" default="#0F2533" value="#0F2533"/>
*/



/* ---------- Base ---------- */
*, *::before, *::after { box-sizing: border-box; }
html {
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
  scroll-padding-top: calc(76px + 16px);
}
body {
  margin: 0;
  font-family: 'Inter', 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  font-size: 17px;
  line-height: 1.7;
  color: $(text.color);
  background: #FFFFFF;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}
html.no-scroll, html.no-scroll body { overflow: hidden; }
img, video, iframe, embed, object { max-width: 100%; }
img { height: auto; border: 0; }
a { color: $(primary.color); text-decoration: none; }
a:hover { color: $(accent.deep.color); }
p { margin: 0 0 1em; }
h1, h2, h3, h4, h5, h6 { margin: 0 0 0.5em; line-height: 1.2; color: $(heading.color); font-weight: 700; }
button, input, select, textarea { font: inherit; color: inherit; }
/* "body" prefix: Blogger injects its own widget stylesheet, sometimes after this skin */
body .section, body .widget { margin: 0; padding: 0; }
body .widget ul, body .widget ol { list-style: none; margin: 0; padding: 0; }
body .widget li { margin: 0; padding: 0; }
:focus-visible { outline: 3px solid $(accent.color); outline-offset: 3px; }

.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0;
}
.skip-link {
  position: absolute; left: 16px; top: -60px; z-index: 200;
  background: $(primary.color); color: #FFFFFF; padding: 10px 16px; border-radius: 8px;
}
.skip-link:focus { top: 12px; color: #FFFFFF; }

.container { width: 100%; max-width: 1200px; margin: 0 auto; padding: 0 20px; }
@media (min-width: 768px) { .container { padding: 0 32px; } }

/* Homepage-only and other-page-only blocks. The <head> reveals .home-only on
   the homepage (it also works with ?fbclid= / ?m=1 thanks to canonicalUrl). */
.home-only { display: none; }
.error-only { display: none; }
.error_page .error-only { display: block; }
.error_page .page-hero, .error_page .news { display: none; }
.navbar-hidden, .bg-source { display: none; }

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  min-height: 46px; padding: 10px 22px; border-radius: 999px; white-space: nowrap;
  font-family: 'Inter', 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; font-size: 15px; font-weight: 600; line-height: 1.2;
  border: 2px solid transparent; cursor: pointer; text-align: center;
  transition: background-color .2s ease, color .2s ease, border-color .2s ease, transform .2s ease, box-shadow .2s ease;
}
.btn:hover { transform: translateY(-1px); }
.btn-primary { background: $(primary.color); color: #FFFFFF; }
.btn-primary:hover { background: $(primary.deep.color); color: #FFFFFF; }
.btn-accent { background: $(accent.color); color: $(heading.color); }
.btn-accent:hover { background: #9BCB5A; color: $(heading.color); box-shadow: 0 6px 18px rgba(135, 186, 69, 0.35); }
.btn-outline { background: transparent; color: $(primary.color); border-color: $(primary.color); }
.btn-outline:hover { background: $(primary.color); color: #FFFFFF; }
.btn-light { background: rgba(255, 255, 255, 0.12); color: #FFFFFF; border-color: rgba(255, 255, 255, 0.55); }
.btn-light:hover { background: #FFFFFF; color: $(primary.deep.color); border-color: #FFFFFF; }
.btn-block { display: flex; width: 100%; }
.btn-row { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 1.5em; }
.text-link, .card-link { font-weight: 600; color: $(primary.color); }
.text-link::after, .card-link::after { content: ' \2192'; }
.text-link:hover, .card-link:hover { color: $(accent.deep.color); }
.badge {
  display: inline-block; padding: 3px 12px; border-radius: 999px;
  background: #E8F1F6; color: $(primary.color); font-size: 12px; font-weight: 600;
  letter-spacing: .02em; line-height: 1.6;
}
.badge:hover { background: $(primary.color); color: #FFFFFF; }

/* ---------- Header ---------- */
.site-header {
  position: sticky; top: 0; z-index: 100;
  background: rgba(255, 255, 255, 0.97);
  border-bottom: 1px solid transparent;
  transition: box-shadow .25s ease, border-color .25s ease;
}
.site-header.is-scrolled { box-shadow: 0 6px 24px rgba(15, 37, 51, 0.08); border-bottom-color: #DCE5EB; }
.header-inner { display: flex; align-items: center; gap: 16px; min-height: 76px; }
.brand-section { flex: 0 0 auto; }
.brand { display: flex; align-items: center; }
.brand-logo { display: block; height: 56px; width: auto; max-width: 240px; object-fit: contain; object-position: left center; }
@media (max-width: 420px) { .brand-logo { max-width: 200px; height: 48px; } }
.brand-name { font-family: 'Fraunces', Georgia, 'Times New Roman', serif; font-size: 22px; color: $(heading.color); font-weight: 700; }

.nav-toggle {
  margin-left: auto; width: 46px; height: 46px; border: 0; border-radius: 12px;
  background: #EEF4F7; color: $(primary.color); cursor: pointer;
  display: inline-flex; align-items: center; justify-content: center;
}
.nav-toggle-bars, .nav-toggle-bars::before, .nav-toggle-bars::after,
.nav-toggle-bars span { display: block; width: 22px; height: 2px; background: currentColor; border-radius: 2px; }
.nav-toggle-bars { position: relative; background: transparent; }
.nav-toggle-bars::before, .nav-toggle-bars::after { content: ''; position: absolute; left: 0; transition: transform .25s ease, top .25s ease; }
.nav-toggle-bars::before { top: -7px; }
.nav-toggle-bars::after { top: 7px; }
.nav-open .nav-toggle-bars span { opacity: 0; }
.nav-open .nav-toggle-bars::before { top: 0; transform: rotate(45deg); }
.nav-open .nav-toggle-bars::after { top: 0; transform: rotate(-45deg); }

.nav-drawer {
  position: fixed; left: 0; right: 0; top: 76px; bottom: 0;
  background: #FFFFFF; padding: 12px 20px 32px; overflow-y: auto;
  border-top: 1px solid #DCE5EB;
  visibility: hidden; opacity: 0; transform: translateY(-8px);
  transition: opacity .2s ease, transform .2s ease, visibility 0s linear .2s;
}
.nav-open .nav-drawer { visibility: visible; opacity: 1; transform: none; transition: opacity .2s ease, transform .2s ease; }
.menu > li { border-bottom: 1px solid #DCE5EB; }
.menu a {
  display: block; padding: 14px 4px; color: $(heading.color); font-weight: 600; font-size: 17px; white-space: nowrap;
}
.menu a:hover, .menu a.is-current { color: $(primary.color); }
.menu .has-sub { position: relative; }
.menu .sub-toggle {
  position: absolute; right: 0; top: 6px; width: 44px; height: 44px; border: 0; background: transparent;
  color: #5B6B76; cursor: pointer; border-radius: 10px;
}
.menu .sub-toggle::before { content: '\25BE'; font-size: 16px; display: inline-block; transition: transform .2s ease; }
.menu .has-sub.sub-open > .sub-toggle::before { transform: rotate(180deg); }
.menu .submenu { display: none; padding: 0 0 10px 14px; }
.menu .has-sub.sub-open > .submenu { display: block; }
.menu .submenu a { padding: 10px 4px; font-weight: 500; font-size: 16px; color: $(text.color); }
.header-cta { margin-top: 20px; }
.header-cta .btn { width: 100%; min-height: 50px; font-size: 16px; }

@media (min-width: 1100px) {
  html:not(.nav-collapse) .nav-toggle { display: none; }
  html:not(.nav-collapse) .nav-drawer {
    position: static; display: flex; align-items: center; gap: 22px; margin-left: auto;
    padding: 0; border: 0; overflow: visible; background: transparent;
    visibility: visible; opacity: 1; transform: none; transition: none;
  }
  html:not(.nav-collapse) .menu { display: flex; align-items: center; gap: 4px; }
  html:not(.nav-collapse) .menu > li { border: 0; position: relative; }
  html:not(.nav-collapse) .menu > li > a { padding: 10px 11px; font-size: 15px; border-radius: 8px; }
  html:not(.nav-collapse) .menu > li > a:hover { background: #EEF4F7; }
  html:not(.nav-collapse) .menu .has-sub > a { padding-right: 26px; }
  html:not(.nav-collapse) .menu .sub-toggle { top: 7px; right: 2px; width: 24px; height: 28px; }
  html:not(.nav-collapse) .menu .submenu {
    display: block; position: absolute; left: 0; top: 100%; min-width: 220px; padding: 8px;
    background: #FFFFFF; border-radius: 12px; box-shadow: 0 2px 4px rgba(15, 37, 51, 0.08), 0 18px 40px rgba(15, 37, 51, 0.14);
    opacity: 0; visibility: hidden; transform: translateY(6px);
    transition: opacity .18s ease, transform .18s ease, visibility 0s linear .18s;
  }
  html:not(.nav-collapse) .menu .has-sub:hover > .submenu, html:not(.nav-collapse) .menu .has-sub:focus-within > .submenu, html:not(.nav-collapse) .menu .has-sub.sub-open > .submenu {
    opacity: 1; visibility: visible; transform: none; transition: opacity .18s ease, transform .18s ease;
  }
  html:not(.nav-collapse) .menu .submenu a { padding: 9px 12px; border-radius: 8px; font-size: 15px; }
  html:not(.nav-collapse) .menu .submenu a:hover { background: #EEF4F7; }
  html:not(.nav-collapse) .header-cta { margin: 0; }
  html:not(.nav-collapse) .header-cta .btn { width: auto; min-height: 44px; font-size: 15px; padding: 10px 24px; }
}

/* ---------- Hero slider ---------- */
.hero { position: relative; overflow: hidden; background: $(primary.deep.color); color: #FFFFFF; }
.hero-images, .hero-images .widget, .hero-shade { position: absolute; inset: 0; }
.hero-images .widget { opacity: 0; transition: opacity 1s ease; }
.hero-images .widget:first-child, .hero-images .widget.is-active { opacity: 1; }
.hero.is-ready .hero-images .widget:first-child:not(.is-active) { opacity: 0; }
.hero-images figure, .hero-images a { display: block; margin: 0; height: 100%; }
.hero-images img { width: 100%; height: 100%; object-fit: cover; }
.hero-images .widget.is-active img { animation: hero-zoom 9s ease-out both; }
@keyframes hero-zoom { from { transform: scale(1.06); } to { transform: scale(1); } }
.hero-shade {
  background:
    linear-gradient(90deg, rgba(8, 36, 52, 0.88) 0%, rgba(8, 36, 52, 0.62) 50%, rgba(8, 36, 52, 0.25) 100%),
    linear-gradient(0deg, rgba(8, 36, 52, 0.55) 0%, rgba(8, 36, 52, 0) 45%);
}
.hero-inner {
  position: relative; display: flex; flex-direction: column; justify-content: center;
  min-height: min(82vh, 720px); padding-top: 64px; padding-bottom: 64px;
}
.hero-slides { display: grid; max-width: 640px; }
.hero-slides .widget { grid-area: 1 / 1; opacity: 0; visibility: hidden; transform: translateY(14px); transition: opacity .7s ease, transform .7s ease, visibility 0s linear .7s; }
.hero-slides .widget:first-child, .hero-slides .widget.is-active { opacity: 1; visibility: visible; transform: none; transition: opacity .7s ease .15s, transform .7s ease .15s; }
.hero.is-ready .hero-slides .widget:first-child:not(.is-active) { opacity: 0; visibility: hidden; transform: translateY(14px); }
.hero-slides .widget-content::before {
  content: 'Murdock Emisembe Foundation'; display: inline-block; margin-bottom: 18px;
  padding: 5px 14px; border-radius: 999px; background: rgba(135, 186, 69, 0.18);
  border: 1px solid rgba(135, 186, 69, 0.55); color: #CDE6AE;
  font-size: 13px; font-weight: 600; letter-spacing: .04em;
}
.slide-title {
  font-family: 'Fraunces', Georgia, 'Times New Roman', serif; font-size: clamp(36px, 6vw, 64px); line-height: 1.05;
  color: #FFFFFF; margin-bottom: 18px; letter-spacing: -0.01em;
}
.hero-slides p { font-size: clamp(17px, 1.6vw, 20px); color: rgba(255, 255, 255, 0.88); max-width: 560px; }
.hero-slides .btn { margin-top: 10px; }
.hero-controls { display: flex; align-items: center; gap: 14px; margin-top: 40px; }
.hero-arrow {
  width: 48px; height: 48px; border-radius: 50%; border: 1px solid rgba(255, 255, 255, 0.45);
  background: rgba(255, 255, 255, 0.08); color: #FFFFFF; cursor: pointer; font-size: 22px; line-height: 1;
  transition: background-color .2s ease, color .2s ease;
}
.hero-arrow:hover { background: #FFFFFF; color: $(primary.deep.color); }
.hero-dots { display: flex; gap: 8px; }
.hero-dot {
  width: 34px; height: 4px; padding: 0; border: 0; border-radius: 4px; cursor: pointer;
  background: rgba(255, 255, 255, 0.35); position: relative; overflow: hidden;
}
.hero-dot::after { content: ''; position: absolute; inset: 0; background: $(accent.color); transform: scaleX(0); transform-origin: left; }
.hero-dot.is-active::after { animation: dot-fill 7s linear forwards; }
.hero.is-paused .hero-dot.is-active::after { animation-play-state: paused; }
@keyframes dot-fill { to { transform: scaleX(1); } }

/* ---------- Bands (sections) ---------- */
.band { padding: 88px 0; position: relative; }
.band-light { background: $(sand.color); }
@media (max-width: 767px) { .band { padding: 64px 0; } }
body .section-intro { max-width: 720px; margin: 0 auto 48px; text-align: center; }
.section-title {
  font-family: 'Fraunces', Georgia, 'Times New Roman', serif; font-size: clamp(30px, 4vw, 44px); line-height: 1.12;
  letter-spacing: -0.01em; margin-bottom: 14px;
}
.section-intro .section-title::after {
  content: ''; display: block; width: 56px; height: 4px; border-radius: 4px;
  background: $(accent.color); margin: 18px auto 0;
}
.section-lead { font-size: 18px; color: #5B6B76; }
.section-lead p:last-child { margin-bottom: 0; }

/* Who we are */
.split { display: grid; gap: 48px; align-items: center; }
@media (min-width: 960px) { .split { grid-template-columns: 1fr 1fr; gap: 64px; } }
.split-text .section-title::after { content: ''; display: block; width: 56px; height: 4px; border-radius: 4px; background: $(accent.color); margin-top: 18px; }
.split-text .section-lead { color: $(text.color); }
.split-text .lead { font-size: 21px; line-height: 1.55; color: $(heading.color); }
.video-frame, .map-frame {
  position: relative; border-radius: 14px; overflow: hidden; box-shadow: 0 2px 4px rgba(15, 37, 51, 0.08), 0 18px 40px rgba(15, 37, 51, 0.14);
  background: $(primary.deep.color); aspect-ratio: 16 / 9;
}
.video-frame iframe, .map-frame iframe { position: absolute; inset: 0; width: 100%; height: 100%; border: 0; }
.split-media .widget { position: relative; }
.split-media .widget::before {
  content: ''; position: absolute; right: -10px; bottom: -10px; width: 60%; height: 60%;
  border-radius: 14px; background: $(accent.color); opacity: .35; z-index: -1;
}
.split-media { position: relative; z-index: 0; }

/* Programmes */
.card-grid { display: grid; gap: 20px; }
@media (min-width: 640px) { .card-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1000px) { .card-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 24px; } }
.card-grid .widget {
  background: #FFFFFF; border: 1px solid #DCE5EB; border-radius: 14px;
  padding: 30px 28px; position: relative; overflow: hidden;
  transition: transform .25s ease, box-shadow .25s ease, border-color .25s ease;
}
.card-grid .widget::before {
  content: ''; position: absolute; left: 0; right: 0; top: 0; height: 4px;
  background: linear-gradient(90deg, $(primary.color), $(accent.color)); transform: scaleX(0); transform-origin: left;
  transition: transform .3s ease;
}
.card-grid .widget:hover { transform: translateY(-4px); box-shadow: 0 2px 4px rgba(15, 37, 51, 0.08), 0 18px 40px rgba(15, 37, 51, 0.14); border-color: transparent; }
.card-grid .widget:hover::before { transform: scaleX(1); }
.card-icon {
  display: inline-flex; align-items: center; justify-content: center; width: 58px; height: 58px;
  border-radius: 16px; background: #E8F1F6; color: $(primary.color); font-size: 24px; margin-bottom: 20px;
  transition: background-color .25s ease, color .25s ease;
}
.card-grid .widget:hover .card-icon { background: $(primary.color); color: #FFFFFF; }
.card-grid h3 { font-family: 'Fraunces', Georgia, 'Times New Roman', serif; font-size: 23px; margin-bottom: 10px; }
.card-grid p { color: #5B6B76; font-size: 16px; }
.card-grid p:last-child { margin-bottom: 0; }

/* Photo frames: the whole picture stays visible (posters keep their text), centred
   over a darkened, enlarged copy of itself so the frame is always filled. JS adds the
   copy; without JS the frame is plain blue. */
.fit-frame { position: relative; display: block; overflow: hidden; background-color: $(primary.deep.color); }
.fit-blur {
  position: absolute; top: -30px; right: -30px; bottom: -30px; left: -30px;
  background-size: cover; background-position: center; transform: scale(1.25);
}
.fit-frame img { position: relative; z-index: 1; display: block; width: 100%; height: 100%; object-fit: contain; }

/* Projects gallery */
.gallery { display: grid; gap: 14px; grid-template-columns: minmax(0, 1fr); }
@media (min-width: 480px) { .gallery { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 900px) { .gallery { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 20px; } }
.gallery-item { margin: 0; }
.gallery-link { aspect-ratio: 4 / 3; border-radius: 14px; box-shadow: 0 1px 2px rgba(15, 37, 51, 0.06), 0 8px 24px rgba(15, 37, 51, 0.08); }
.gallery-link img { transition: transform .6s ease; }
.gallery-link::after { content: ''; position: absolute; inset: 0; z-index: 1; background: linear-gradient(0deg, rgba(11, 51, 73, 0.55), rgba(11, 51, 73, 0) 50%); opacity: 0; transition: opacity .3s ease; }
.gallery-zoom {
  position: absolute; right: 14px; bottom: 14px; z-index: 2; width: 42px; height: 42px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center; background: #FFFFFF; color: $(primary.color);
  opacity: 0; transform: translateY(8px); transition: opacity .3s ease, transform .3s ease;
}
.gallery-link:hover img, .gallery-link:focus-visible img { transform: scale(1.03); }
.gallery-link:hover::after, .gallery-link:hover .gallery-zoom,
.gallery-link:focus-visible::after, .gallery-link:focus-visible .gallery-zoom { opacity: 1; transform: none; }
.gallery .img-caption { font-size: 14px; color: #5B6B76; padding-top: 8px; }

/* Photo bands (get involved, partners, contact): a photo set by JS from a hidden Image gadget */
.band-photo { background-color: $(primary.deep.color); background-size: cover; background-position: center; color: #FFFFFF; }
.band-photo::before {
  content: ''; position: absolute; inset: 0;
  background: linear-gradient(120deg, rgba(11, 51, 73, 0.94), rgba(20, 84, 116, 0.82));
}
.band-photo > .container { position: relative; }
.cta-band { max-width: 820px; margin: 0 auto; text-align: center; }
.band-title { font-family: 'Fraunces', Georgia, 'Times New Roman', serif; font-size: clamp(28px, 4vw, 42px); color: #FFFFFF; line-height: 1.15; }
.band-text { font-size: 18px; color: rgba(255, 255, 255, 0.86); }
.cta-band .btn-row { justify-content: center; }

/* News */
.main-grid { display: grid; gap: 48px; }
@media (min-width: 1000px) { .main-grid { grid-template-columns: minmax(0, 1fr) 320px; } }
.post-grid { display: grid; gap: 24px; }
@media (min-width: 640px) { .post-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.post-card {
  display: flex; flex-direction: column; background: #FFFFFF; border: 1px solid #DCE5EB;
  border-radius: 14px; overflow: hidden; transition: transform .25s ease, box-shadow .25s ease;
}
.post-card:hover { transform: translateY(-4px); box-shadow: 0 2px 4px rgba(15, 37, 51, 0.08), 0 18px 40px rgba(15, 37, 51, 0.14); }
.post-card-media { aspect-ratio: 16 / 10; background-image: linear-gradient(135deg, $(primary.color), $(primary.deep.color)); }
.post-card-media img { transition: transform .6s ease; }
.post-card:hover .post-card-media img { transform: scale(1.03); }
@media (max-width: 639px) { .post-card-media { aspect-ratio: 4 / 3; } }
.post-card-placeholder { position: relative; z-index: 1; display: flex; align-items: center; justify-content: center; height: 100%; color: rgba(255, 255, 255, 0.7); font-size: 40px; }
.post-card-body { display: flex; flex-direction: column; align-items: flex-start; gap: 8px; padding: 22px 24px 26px; flex: 1; }
.post-card-labels .badge:nth-child(n+2) { display: none; }
.post-card-title { font-family: 'Fraunces', Georgia, 'Times New Roman', serif; font-size: 22px; line-height: 1.25; margin: 4px 0 0; }
.post-card-title a { color: $(heading.color); }
.post-card-title a:hover { color: $(primary.color); }
.post-card-meta { margin: 0; font-size: 14px; color: #5B6B76; }
.post-card-excerpt { margin: 0; font-size: 15.5px; color: #5B6B76; }
.post-card-excerpt:empty { display: none; }
.post-card .text-link { margin-top: auto; padding-top: 6px; font-size: 15px; }
.list-pager { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 12px; margin-top: 36px; }
.list-pager .btn-primary { margin-left: auto; }
.all-stories { text-align: center; margin: 36px 0 0; }
.empty-state { text-align: center; padding: 48px 20px; background: $(sand.color); border-radius: 14px; }

/* Homepage: full-width news with up to six stories (rules in the <head> homepage <style>) */

/* Page header on non-home pages */
.page-hero { background-color: $(primary.deep.color); background-size: cover; background-position: center; color: #FFFFFF; position: relative; padding: 72px 0 64px; }
.page-hero::before { content: ''; position: absolute; inset: 0; background: linear-gradient(120deg, rgba(11, 51, 73, 0.95), rgba(20, 84, 116, 0.85)); }
.page-hero .container { position: relative; }
.page-hero .eyebrow { margin: 0 0 8px; font-size: 13px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; color: #CDE6AE; }
.page-title { font-family: 'Fraunces', Georgia, 'Times New Roman', serif; font-size: clamp(32px, 5vw, 52px); color: #FFFFFF; margin: 0; }
.page-lead { margin: 14px 0 0; max-width: 680px; font-size: 18px; color: rgba(255, 255, 255, 0.85); }
.item .page-hero, .static_page .page-hero { display: none; }
.item .news, .static_page .news { padding-top: 48px; }

/* Single post */
.post-single { max-width: 760px; }
.post-head { margin-bottom: 28px; }
.post-labels { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 16px; }
.post-title { font-family: 'Fraunces', Georgia, 'Times New Roman', serif; font-size: clamp(32px, 4.6vw, 48px); line-height: 1.12; letter-spacing: -0.01em; margin-bottom: 14px; }
.post-meta { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; color: #5B6B76; font-size: 15px; margin: 0; }
.post-author { font-weight: 600; color: $(heading.color); }
.post-body { font-size: 18px; line-height: 1.8; overflow-wrap: break-word; }
.post-body h2, .post-body h3, .post-body h4 { font-family: 'Fraunces', Georgia, 'Times New Roman', serif; margin: 1.6em 0 .5em; }
.post-body h2 { font-size: 30px; }
.post-body h3 { font-size: 24px; }
.post-body a { text-decoration: underline; text-decoration-color: rgba(20, 84, 116, 0.35); text-underline-offset: 3px; }
.post-body a:hover { text-decoration-color: $(accent.color); }
.post-body img { border-radius: 10px; }
/* Photos in posts: Blogger inserts them small (s320/s400) and floated; show them
   full width and sharp (JS swaps in a large copy). Small originals stay their size. */
.post-body .separator, .post-body .tr-caption-container { clear: both; float: none !important; margin: 1.6em auto !important; text-align: center; }
.post-body .separator a, .post-body .tr-caption-container a { display: block; float: none !important; margin-left: 0 !important; margin-right: 0 !important; }
.post-body img.post-photo { display: block; width: 100%; height: auto; max-width: 100%; margin: 0 auto; box-shadow: 0 1px 2px rgba(15, 37, 51, 0.06), 0 8px 24px rgba(15, 37, 51, 0.08); background: #EEF4F7; }
.post-body img.post-photo.is-small { width: auto; }
.post-body .tr-caption-container { width: 100% !important; }
.post-body .tr-caption { padding-top: 8px; font-size: 14px; color: #5B6B76; }
.post-body blockquote {
  margin: 1.5em 0; padding: 18px 24px; border-left: 4px solid $(accent.color);
  background: $(sand.color); border-radius: 0 10px 10px 0; font-family: 'Fraunces', Georgia, 'Times New Roman', serif; font-size: 21px; color: $(heading.color);
}
.post-body iframe { display: block; margin: 1em auto; border-radius: 10px; }
.post-body table { border-collapse: collapse; width: 100%; }
.post-body td, .post-body th { border: 1px solid #DCE5EB; padding: 8px 12px; }
body .widget .post-body ul, body .widget .post-body ol { margin: 0 0 1.2em; padding-left: 1.4em; }
body .widget .post-body ul { list-style: disc; }
body .widget .post-body ol { list-style: decimal; }
body .widget .post-body li { margin: .3em 0; padding: 0; }
.post-share { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; margin: 40px 0 0; padding: 22px 0; border-top: 1px solid #DCE5EB; border-bottom: 1px solid #DCE5EB; }
.post-share-label { width: 100%; font-weight: 700; color: $(heading.color); font-size: 15px; }
.post-share a, .post-share button {
  display: inline-flex; align-items: center; gap: 7px; min-height: 40px; padding: 8px 16px;
  border-radius: 999px; border: 1px solid #DCE5EB; background: #FFFFFF;
  font-size: 14px; font-weight: 600; color: $(heading.color); cursor: pointer;
}
.post-share a:hover, .post-share button:hover { background: $(primary.color); border-color: $(primary.color); color: #FFFFFF; }
.post-share .share-whatsapp:hover { background: #128C4B; border-color: #128C4B; }
.related { margin-top: 44px; }
.related-label { display: none; }
.related-title { font-family: 'Fraunces', Georgia, 'Times New Roman', serif; font-size: 26px; }
.related-grid { display: grid; gap: 18px; }
@media (min-width: 640px) { .related-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
.related-card { display: block; border-radius: 12px; overflow: hidden; background: #FFFFFF; border: 1px solid #DCE5EB; color: $(heading.color); transition: box-shadow .25s ease, transform .25s ease; }
.related-card:hover { box-shadow: 0 1px 2px rgba(15, 37, 51, 0.06), 0 8px 24px rgba(15, 37, 51, 0.08); transform: translateY(-3px); color: $(primary.color); }
.related-card .fit-frame, .related-card .related-ph { display: block; width: 100%; aspect-ratio: 16 / 10; background-image: linear-gradient(135deg, $(primary.color), $(primary.deep.color)); }
.related-card .related-name { display: block; padding: 12px 14px 14px; font-weight: 600; font-size: 15px; line-height: 1.4; }
.post-cta {
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 16px;
  margin-top: 44px; padding: 24px 28px; border-radius: 14px; background: $(sand.color);
  border-left: 5px solid $(accent.color);
}
.post-cta p { margin: 0; color: $(heading.color); }
.item-pager { display: grid; gap: 14px; margin-top: 44px; }
@media (min-width: 640px) { .item-pager { grid-template-columns: 1fr 1fr; } }
.item-pager-link { display: block; padding: 18px 20px; border-radius: 12px; border: 1px solid #DCE5EB; color: $(heading.color); }
.item-pager-link span { display: block; font-size: 13px; font-weight: 600; color: #5B6B76; text-transform: uppercase; letter-spacing: .06em; }
.item-pager-link strong { display: block; margin-top: 4px; font-family: 'Fraunces', Georgia, 'Times New Roman', serif; font-size: 18px; line-height: 1.3; }
.item-pager-link.older { text-align: right; grid-column: 2; }
@media (max-width: 639px) { .item-pager-link.older { grid-column: auto; } }
.item-pager-link:hover { border-color: $(primary.color); color: $(primary.color); }
.item-control { margin-left: 6px; }

/* Comments (Blogger's own markup) */
.post-comments { margin-top: 48px; }
.comments h3 { font-family: 'Fraunces', Georgia, 'Times New Roman', serif; font-size: 26px; }
.comments .comment-block, .comments .comment-content { overflow-wrap: break-word; }
.comments .comments-content .comment-thread ol { padding-left: 0; }
.comments .comments-content .comment { margin-bottom: 16px; padding: 16px 18px; background: #F6F9FB; border-radius: 12px; }
.comments .avatar-image-container img { border-radius: 50%; }
.comments .comment-replies { margin-left: 24px; }
.comment-form iframe { width: 100%; }

/* Sidebar */
.sidebar-section { display: grid; gap: 24px; align-content: start; }
@media (min-width: 1000px) { .sidebar-section { position: sticky; top: calc(76px + 20px); } }
.sidebar-section > .widget { background: #FFFFFF; border: 1px solid #DCE5EB; border-radius: 14px; padding: 24px; }
.sidebar-section > .widget.HTML:first-child { border: 0; padding: 0; background: transparent; }
.side-card-accent { padding: 26px 24px; border-radius: 14px; background: $(primary.color); color: rgba(255, 255, 255, 0.88); }
.side-card-accent .card-title { color: #FFFFFF; }
.card-title { font-family: 'Fraunces', Georgia, 'Times New Roman', serif; font-size: 21px; margin-bottom: 14px; }
body .mini-posts li { display: flex; gap: 14px; align-items: center; padding: 12px 0; border-top: 1px solid #DCE5EB; }
body .mini-posts li:first-child { border-top: 0; padding-top: 0; }
.mini-thumb { flex: 0 0 64px; }
.mini-thumb img { width: 64px; height: 64px; object-fit: cover; border-radius: 10px; display: block; }
.mini-title { font-weight: 600; color: $(heading.color); line-height: 1.4; font-size: 15px; }
.mini-title:hover { color: $(primary.color); }
.mini-snippet { margin: 4px 0 0; font-size: 14px; color: #5B6B76; }
.featured-media { border-radius: 10px; aspect-ratio: 16 / 10; margin-bottom: 12px; }
.featured-title { font-family: 'Fraunces', Georgia, 'Times New Roman', serif; font-size: 19px; margin-bottom: 8px; }
.featured-title a { color: $(heading.color); }
.featured-snippet { font-size: 15px; color: #5B6B76; margin-bottom: 8px; }

/* Team */
.team-grid { display: grid; gap: 24px; }
@media (min-width: 640px) { .team-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 960px) { .team-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 28px; } }
.team-grid .img-gadget { margin: 0; height: 100%; background: #FFFFFF; border-radius: 14px; overflow: hidden; box-shadow: 0 1px 2px rgba(15, 37, 51, 0.06), 0 8px 24px rgba(15, 37, 51, 0.08); text-align: center; }
.team-grid .img-gadget > img, .team-grid .img-gadget > a > img { display: block; width: 100%; aspect-ratio: 4 / 4.2; object-fit: cover; object-position: center 20%; }
.team-grid .img-caption { padding: 22px 24px 26px; }
.team-grid .name { font-family: 'Fraunces', Georgia, 'Times New Roman', serif; font-size: 23px; margin: 0 0 2px; }
.team-grid .role, .team-grid .activity { margin: 0 0 12px; color: $(accent.deep.color); font-weight: 600; font-size: 14px; letter-spacing: .04em; text-transform: uppercase; }
.team-grid .bio, .team-grid .text { font-size: 15.5px; color: #5B6B76; }

/* Social icons (team cards and footer): links still set to "#" stay hidden until a real address is added */
.social { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin: 0; }
.social a {
  display: inline-flex; align-items: center; justify-content: center; width: 40px; height: 40px;
  border-radius: 50%; background: #E8F1F6; color: $(primary.color); font-size: 17px;
  transition: background-color .2s ease, color .2s ease, transform .2s ease;
}
.social a:hover { background: $(primary.color); color: #FFFFFF; transform: translateY(-2px); }
.social a[href="#"], .social a[href=""] { display: none; }

/* Partners */
.band-partners .section-title, .on-dark .section-title { color: #FFFFFF; }
.on-dark .section-lead { color: rgba(255, 255, 255, 0.82); }
.logo-grid { display: grid; gap: 16px; grid-template-columns: repeat(2, minmax(0, 1fr)); }
@media (min-width: 640px) { .logo-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
@media (min-width: 1000px) { .logo-grid { grid-template-columns: repeat(6, minmax(0, 1fr)); } }
.logo-grid .img-gadget {
  margin: 0; height: 120px; display: flex; align-items: center; justify-content: center; padding: 18px;
  background: #FFFFFF; border-radius: 14px; transition: transform .25s ease, box-shadow .25s ease;
}
.logo-grid .img-gadget:hover { transform: translateY(-3px); box-shadow: 0 12px 30px rgba(0, 0, 0, 0.25); }
.logo-grid img { max-height: 84px; width: auto; object-fit: contain; filter: grayscale(0.15); }
.logo-grid .img-caption { display: none; }

/* Contact */
.band-contact { background-color: $(sand.color); background-size: cover; background-position: center; }
.band-contact::before { content: ''; position: absolute; inset: 0; background: rgba(246, 238, 227, 0.93); }
.band-contact > .container { position: relative; }
.contact-grid { display: grid; gap: 40px; align-items: start; }
@media (min-width: 960px) { .contact-grid { grid-template-columns: 1fr 1fr; gap: 56px; } }
.contact-info .section-title::after { content: ''; display: block; width: 56px; height: 4px; border-radius: 4px; background: $(accent.color); margin-top: 18px; }
.contact-info .section-lead { color: $(text.color); }
body .contact-list { margin: 20px 0 28px; padding: 0; list-style: none; }
body .contact-list li { display: flex; align-items: center; gap: 12px; padding: 8px 0; }
.contact-list i { width: 38px; height: 38px; border-radius: 50%; background: #FFFFFF; color: $(primary.color); display: inline-flex; align-items: center; justify-content: center; flex: 0 0 38px; }
.contact-list a { font-weight: 600; }
.contact-info .map-frame { aspect-ratio: 16 / 10; }
body .contact-form-card { background: #FFFFFF; border-radius: 18px; padding: 32px 24px; box-shadow: 0 2px 4px rgba(15, 37, 51, 0.08), 0 18px 40px rgba(15, 37, 51, 0.14); }
@media (min-width: 640px) { body .contact-form-card { padding: 40px; } }
.contact-form { display: grid; gap: 18px; }
.field { display: grid; gap: 6px; font-weight: 600; font-size: 14px; color: $(heading.color); }
.form-control {
  width: 100%; padding: 13px 16px; border: 1.5px solid #DCE5EB; border-radius: 10px;
  background: #FAFCFD; font-size: 16px; font-weight: 400; color: $(heading.color);
  transition: border-color .2s ease, box-shadow .2s ease;
}
.form-control:focus { outline: none; border-color: $(primary.color); box-shadow: 0 0 0 4px rgba(20, 84, 116, 0.15); background: #FFFFFF; }
textarea.form-control { resize: vertical; min-height: 140px; }
.contact-button { width: 100%; min-height: 52px; font-size: 16px; }
.contact-form-error-message, .contact-form-success-message { margin: 0; font-size: 15px; }
.contact-form-error-message:empty, .contact-form-success-message:empty { display: none; }
.contact-form-error-message { color: #B42318; }
.contact-form-success-message { color: $(accent.deep.color); font-weight: 600; }

/* 404 */
.not-found { max-width: 640px; margin: 0 auto; text-align: center; }
.not-found-code { font-family: 'Inter', 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; font-weight: 800; letter-spacing: -0.04em; font-size: clamp(90px, 18vw, 160px); line-height: 1; margin: 0; color: transparent; background: linear-gradient(135deg, $(primary.color), $(accent.color)); -webkit-background-clip: text; background-clip: text; }
.not-found .btn-row { justify-content: center; }
.search-form { display: flex; max-width: 440px; margin: 28px auto 0; border: 1.5px solid #DCE5EB; border-radius: 999px; overflow: hidden; background: #FFFFFF; }
.search-form input { flex: 1; min-width: 0; border: 0; padding: 12px 18px; background: transparent; }
.search-form input:focus { outline: none; }
.search-form button { border: 0; background: $(primary.color); color: #FFFFFF; width: 52px; cursor: pointer; }

/* ---------- Footer ---------- */
.site-footer { background: $(primary.deep.color); color: rgba(255, 255, 255, 0.75); font-size: 15.5px; }
.footer-grid { display: grid; gap: 40px; padding-top: 72px; padding-bottom: 48px; }
@media (min-width: 640px) { .footer-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1000px) { .footer-grid { grid-template-columns: 1.5fr 1fr 1fr 1fr; gap: 48px; } }
.footer-title { font-family: 'Fraunces', Georgia, 'Times New Roman', serif; font-size: 20px; color: #FFFFFF; margin-bottom: 18px; }
.footer-about .footer-title { font-size: 24px; }
.site-footer a { color: rgba(255, 255, 255, 0.85); }
.site-footer a:hover { color: $(accent.color); }
.footer-col .widget + .widget { margin-top: 28px; }
body .footer-col li { padding: 5px 0; }
.footer-col .social { justify-content: flex-start; }
.site-footer .social a { background: rgba(255, 255, 255, 0.1); color: #FFFFFF; }
.site-footer .social a:hover { background: $(accent.color); color: $(heading.color); }
.logo-row { display: flex; flex-wrap: wrap; gap: 12px; }
.logo-row a { display: inline-flex; width: 84px; height: 84px; align-items: center; justify-content: center; border-radius: 12px; background: #FFFFFF; padding: 8px; }
.logo-row img { max-width: 100%; max-height: 100%; width: auto; height: auto; object-fit: contain; }
.footer-bottom { border-top: 1px solid rgba(255, 255, 255, 0.12); }
.footer-bottom-inner { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 10px 24px; padding-top: 22px; padding-bottom: 22px; font-size: 14px; }
.copyright { margin: 0; }
.footer-credit p, .footer-credit .widget-content { margin: 0; }
.footer-translate { margin-left: auto; }
.footer-translate .title, .footer-translate h2 { display: none; }
.footer-translate .goog-te-gadget { color: rgba(255, 255, 255, 0.6) !important; font-size: 12px; font-family: 'Inter', 'Segoe UI', Roboto, Helvetica, Arial, sans-serif !important; }
.footer-translate .goog-te-gadget a, .footer-translate .goog-te-gadget span { color: rgba(255, 255, 255, 0.6) !important; }
.footer-translate select { padding: 6px 8px; border-radius: 8px; border: 0; color: $(heading.color); }
@media (max-width: 767px) {
  .footer-bottom-inner { flex-direction: column; text-align: center; }
  .footer-translate { margin: 0; }
}

.back-to-top {
  position: fixed; right: 18px; bottom: 18px; z-index: 90; width: 48px; height: 48px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center; font-size: 24px;
  background: $(accent.color); color: $(heading.color); box-shadow: 0 2px 4px rgba(15, 37, 51, 0.08), 0 18px 40px rgba(15, 37, 51, 0.14);
  opacity: 0; visibility: hidden; transform: translateY(10px); transition: opacity .25s ease, transform .25s ease, visibility 0s linear .25s;
}
.back-to-top.is-visible { opacity: 1; visibility: visible; transform: none; transition: opacity .25s ease, transform .25s ease; }
.back-to-top:hover { color: $(heading.color); background: #9BCB5A; }

/* ---------- Lightbox ---------- */
.lightbox {
  position: fixed; inset: 0; z-index: 300; display: flex; align-items: center; justify-content: center;
  background: rgba(6, 22, 32, 0.94); padding: 60px 16px;
  opacity: 0; visibility: hidden; transition: opacity .25s ease, visibility 0s linear .25s;
}
.lightbox.is-open { opacity: 1; visibility: visible; transition: opacity .25s ease; }
.lightbox-img { max-width: min(1100px, 100%); max-height: 100%; border-radius: 10px; box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5); }
.lightbox button {
  position: absolute; width: 48px; height: 48px; border-radius: 50%; border: 0; cursor: pointer;
  background: rgba(255, 255, 255, 0.12); color: #FFFFFF; font-size: 30px; line-height: 1;
}
.lightbox button:hover { background: #FFFFFF; color: $(heading.color); }
.lightbox-close { top: 14px; right: 14px; }
.lightbox-prev { left: 14px; top: 50%; margin-top: -24px; }
.lightbox-next { right: 14px; top: 50%; margin-top: -24px; }

/* ---------- Scroll reveal (only when JS is running and motion is OK) ---------- */
.js-reveal .reveal { opacity: 0; transform: translateY(24px); transition: opacity .7s ease, transform .7s ease; }
.js-reveal .reveal.is-visible { opacity: 1; transform: none; }
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
}

/* ---------- Blogger extras ---------- */
.quickedit, .item-control { display: inline-block; }
.widget-item-control { position: relative; z-index: 2; }
.feed-links, .blog-feeds, .status-msg-wrap { display: none; }

/* ---------- Mobile balance (phones) ---------- */
@media (max-width: 767px) {
  .hero-inner { text-align: center; align-items: center; min-height: 600px; }
  .hero-slides { margin: 0 auto; }
  .hero-slides p { margin-left: auto; margin-right: auto; }
  .hero-controls { justify-content: center; }
  .hero-shade { background: linear-gradient(0deg, rgba(8, 36, 52, 0.92) 0%, rgba(8, 36, 52, 0.7) 60%, rgba(8, 36, 52, 0.55) 100%); }
  .split-text, .contact-info { text-align: center; }
  .split-text .section-title::after, .contact-info .section-title::after { margin-left: auto; margin-right: auto; }
  .split-text .btn-row, .band .btn-row { justify-content: center; }
  .contact-list li { justify-content: center; }
  .card-grid .widget { text-align: center; }
  .post-card-body { align-items: center; text-align: center; }
  .list-pager .btn { flex: 1 1 100%; }
  .page-hero { text-align: center; }
  .page-lead { margin-left: auto; margin-right: auto; }
  .footer-grid { text-align: center; }
  .footer-col .social, .logo-row { justify-content: center; }
  .post-share { justify-content: center; }
  .post-share-label { text-align: center; }
  .post-cta { justify-content: center; text-align: center; }
}

/* ---------- Layout editor (Theme > Layout) ---------- */
body#layout .site-header { position: static; }
body#layout .home-only, body#layout .not-home, body#layout .error-only, body#layout .bg-source,
body#layout .navbar-hidden, body#layout .sidebar, body#layout .hero { display: block; }
body#layout .hero-images, body#layout .hero-images .widget, body#layout .hero-shade { position: static; opacity: 1; }
body#layout .hero-slides .widget { opacity: 1; visibility: visible; transform: none; }
body#layout .nav-drawer { position: static; display: block; visibility: visible; opacity: 1; transform: none; }
body#layout .nav-toggle, body#layout .skip-link, body#layout .hero-controls, body#layout .copyright,
body#layout .back-to-top, body#layout .lightbox { display: none; }
body#layout .container { max-width: none; padding: 0; }
body#layout .band, body#layout .page-hero { padding: 10px 0; }
body#layout .band-photo::before, body#layout .page-hero::before { display: none; }
body#layout .reveal { opacity: 1; transform: none; }

head.b:template-skin:
/* Theme > Layout editor */
body#layout { width: 900px; font-family: Arial, sans-serif; }
body#layout .container { max-width: none; padding: 0 10px; }
body#layout .site-header, body#layout .band, body#layout .page-hero, body#layout .site-footer,
body#layout .footer-bottom { position: static; display: block; padding: 6px 0; margin: 0 0 8px; background: none; }
body#layout .home-only, body#layout .not-home, body#layout .error-only, body#layout .bg-source,
body#layout .navbar-hidden, body#layout .sidebar, body#layout .hero, body#layout .nav-drawer { display: block; }
body#layout .hero-images, body#layout .hero-images .widget, body#layout .hero-shade { position: static; opacity: 1; }
body#layout .header-inner, body#layout .split, body#layout .main-grid, body#layout .contact-grid,
body#layout .footer-grid, body#layout .footer-bottom-inner { display: block; }
body#layout .nav-toggle, body#layout .skip-link, body#layout .hero-controls, body#layout .copyright,
body#layout .back-to-top, body#layout .lightbox, body#layout .hero-shade, body#layout .sr-only { display: none; }
body#layout .section { margin: 0 0 6px; }

b:includable.script:
(function() {
  var items = ;
  var msgs = ;
  var config = ;
  // 
  var cursor = null;
  if (items && items.length > 0) {
    cursor = parseInt(items[items.length - 1].timestamp) + 1;
  }
  var bodyFromEntry = function(entry) {
    if (entry.gd$extendedProperty) {
      for (var k in entry.gd$extendedProperty) {
        if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
          return '<span class="deleted-comment">' + entry.content.$t + '</span>';
        }
      }
    }
    return entry.content.$t;
  }
  var parse = function(data) {
    cursor = null;
    var comments = [];
    if (data && data.feed && data.feed.entry) {
      for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
        var comment = {};
        // comment ID, parsed out of the original id format
        var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
        comment.id = id ? id[2] : null;
        comment.body = bodyFromEntry(entry);
        comment.timestamp = Date.parse(entry.published.$t) + '';
        if (entry.author && entry.author.constructor === Array) {
          var auth = entry.author[0];
          if (auth) {
            comment.author = {
              name: (auth.name ? auth.name.$t : undefined),
              profileUrl: (auth.uri ? auth.uri.$t : undefined),
              avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
            };
          }
        }
        if (entry.link) {
          if (entry.link[2]) {
            comment.link = comment.permalink = entry.link[2].href;
          }
          if (entry.link[3]) {
            var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
            if (pid && pid[1]) {
              comment.parentId = pid[1];
            }
          }
        }
        comment.deleteclass = 'item-control blog-admin';
        if (entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
              comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
            } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
              comment.displayTime = entry.gd$extendedProperty[k].value;
            }
          }
        }
        comments.push(comment);
      }
    }
    return comments;
  };
  var paginator = function(callback) {
    if (hasMore()) {
      var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
      if (cursor) {
        url += '&published-min=' + new Date(cursor).toISOString();
      }
      window.bloggercomments = function(data) {
        var parsed = parse(data);
        cursor = parsed.length < 50 ? null
        : parseInt(parsed[parsed.length - 1].timestamp) + 1
        callback(parsed);
        window.bloggercomments = null;
      }
      url += '&callback=bloggercomments';
      var script = document.createElement('script');
      script.type = 'text/javascript';
      script.src = url;
      document.getElementsByTagName('head')[0].appendChild(script);
    }
  };
  var hasMore = function() {
    return !!cursor;
  };
  var getMeta = function(key, comment) {
    if ('iswriter' == key) {
      var matches = !!comment.author
      && comment.author.name == config.authorName
      && comment.author.profileUrl == config.authorUrl;
      return matches ? 'true' : '';
    } else if ('deletelink' == key) {
      return config.baseUri + '/delete-comment.g?blogID='
      + config.blogId + '&postID=' + comment.id;
    } else if ('deleteclass' == key) {
      return comment.deleteclass;
    }
    return '';
  };
  var replybox = null;
  var replyUrlParts = null;
  var replyParent = undefined;
  var onReply = function(commentId, domId) {
    if (replybox == null) {
      // lazily cache replybox, and adjust to suit this style:
      replybox = document.getElementById('comment-editor');
      if (replybox != null) {
        replybox.height = '250px';
        replybox.style.display = 'block';
        replyUrlParts = replybox.src.split('#');
      }
    }
    if (replybox && (commentId !== replyParent)) {
      document.getElementById(domId).insertBefore(replybox, null);
      replybox.src = replyUrlParts[0]
      + (commentId ? '&parentID=' + commentId : '')
      + '#' + replyUrlParts[1];
      replyParent = commentId;
    }
  };
  var hash = (window.location.hash || '#').substring(1);
  var startThread, targetComment;
  if (/^comment-form_/.test(hash)) {
    startThread = hash.substring('comment-form_'.length);
  } else if (/^c[0-9]+$/.test(hash)) {
    targetComment = hash.substring(1);
  }
  // Configure commenting API:
  var configJso = {
    'maxDepth': config.maxThreadDepth
  };
  var provider = {
    'id': config.postId,
    'data': items,
    'loadNext': paginator,
    'hasMore': hasMore,
    'getMeta': getMeta,
    'onReply': onReply,
    'rendered': true,
    'initComment': targetComment,
    'initReplyThread': startThread,
    'config': configJso,
    'messages': msgs
  };
  var render = function() {
    if (window.goog && window.goog.comments) {
      var holder = document.getElementById('comment-holder');
      window.goog.comments.render(holder, provider);
    }
  };
  // render now, or queue to render when library loads:
  if (window.goog && window.goog.comments) {
    render();
  } else {
    window.goog = window.goog || {};
    window.goog.comments = window.goog.comments || {};
    window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
    window.goog.comments.loadQueue.push(render);
  }
})();
//

function googleTranslateElementInit() {
  new google.translate.TranslateElement({
    pageLanguage: '',
    autoDisplay: 'true',
    layout: google.translate.TranslateElement.InlineLayout.
  }, 'google_translate_element');
}

body.script:
//
// Murdock Emisembe Foundation theme behaviour. Plain JavaScript, no libraries.
// Menu and submenus, hero slider, photo backgrounds, gallery lightbox, story
// excerpts, related stories, share/copy link, scroll reveal and back-to-top.
(function () {
  'use strict';
  var doc = document;
  var root = doc.documentElement;
  var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function $(sel, ctx) { return (ctx || doc).querySelector(sel); }
  function $all(sel, ctx) { return Array.prototype.slice.call((ctx || doc).querySelectorAll(sel)); }
  function el(tag, cls, text) {
    var n = doc.createElement(tag);
    if (cls) n.className = cls;
    if (text) n.textContent = text;
    return n;
  }

  // ---------------------------------------------------------------- images
  // Ask Blogger's image server for a sensible size (Google-hosted images only).
  var googleImage = /^(https?:)?\/\/([a-z0-9-]+\.)*(googleusercontent\.com|blogspot\.com|ggpht\.com)\//i;
  function sized(src, size) {
    if (!src || !googleImage.test(src)) return src;
    return src
      .replace(/\/s\d+(-[a-z0-9]+)*\//i, '/' + size + '/')
      .replace(/\/w\d+-h\d+(-[a-z0-9]+)*\//i, '/' + size + '/')
      .replace(/=s\d+(-[a-z0-9]+)*$/i, '=' + size)
      .replace(/=w\d+-h\d+(-[a-z0-9]+)*$/i, '=' + size);
  }
  var youtubeThumb = /^(https?:\/\/(img\.youtube\.com|i\.ytimg\.com)\/vi\/[^/]+\/)[a-z]*default\.jpg$/i;
  // Card and gallery photos: a sharp, UNCROPPED copy (posters keep their text)
  $all('img.js-resize').forEach(function (img) {
    var src = img.getAttribute('src') || '';
    var out = youtubeThumb.test(src) ? src.replace(youtubeThumb, '$1hqdefault.jpg') : sized(src, 's900');
    if (out !== src) img.setAttribute('src', out);
  });
  $all('.gallery-link img').forEach(function (img) {
    var src = img.getAttribute('src') || '';
    var out = sized(src, 's1000');
    if (out !== src) img.setAttribute('src', out);
  });

  // Photo frames: fill the frame with a darkened, enlarged copy of the picture behind it
  function fillFrame(frame) {
    var img = frame.querySelector('img');
    var src = img && img.getAttribute('src');
    if (!src || frame.querySelector('.fit-blur')) return;
    var blur = el('span', 'fit-blur');
    blur.setAttribute('aria-hidden', 'true');
    blur.style.backgroundImage = 'linear-gradient(rgba(11, 51, 73, 0.66), rgba(11, 51, 73, 0.66)), url("' + src.replace(/"/g, '%22') + '")';
    frame.insertBefore(blur, frame.firstChild);
  }
  $all('.fit-frame').forEach(fillFrame);

  // Photos inside a post: Blogger inserts them small (s320/s400). Load a large copy
  // and show it across the column; originals smaller than ~60% of it keep their size.
  $all('.post-body img').forEach(function (img) {
    var src = img.getAttribute('src') || '';
    var w = parseInt(img.getAttribute('width'), 10);
    if (!googleImage.test(src) || (w && w < 120)) return;  // icons, emoji, tracking pixels
    img.classList.add('post-photo');
    img.removeAttribute('width');
    img.removeAttribute('height');
    var big = sized(src, 's1600');
    if (big !== src) img.setAttribute('src', big);
    var check = function () {
      var col = img.parentNode && img.closest('.post-body');
      if (col && img.naturalWidth && img.naturalWidth < col.clientWidth * 0.6) img.classList.add('is-small');
    };
    if (img.complete) check(); else img.addEventListener('load', check);
  });
  $all('img.js-resize-square').forEach(function (img) {
    var src = img.getAttribute('src') || '';
    var out = sized(src, 's128-c');
    if (out !== src) img.setAttribute('src', out);
  });

  // Photo sections take their background from a hidden Image gadget (editable in Layout)
  $all('[data-bg-from]').forEach(function (band) {
    var img = $('#' + band.getAttribute('data-bg-from') + ' img');
    var src = img && img.getAttribute('src');
    if (src) band.style.backgroundImage = 'url("' + sized(src, 'w1920').replace(/"/g, '%22') + '")';
  });

  // ---------------------------------------------------------------- header and menu
  var header = $('#site-header');
  var toggle = $('#nav-toggle');
  var drawer = $('#site-nav');
  var desktop = window.matchMedia ? window.matchMedia('(min-width: 1100px)') : null;

  // Menu items written as "_Name" in the Menu gadget become a dropdown under the item above them
  var menu = $('.menu');
  if (menu) {
    var parent = null;
    $all('.menu > li', menu).forEach(function (li) {
      var a = li.querySelector('a');
      if (!a) return;
      var label = a.textContent.replace(/^\s+|\s+$/g, '');
      if (label.charAt(0) === '_' && parent) {
        a.textContent = label.replace(/^_+\s*/, '');
        var sub = parent.querySelector('.submenu');
        if (!sub) {
          sub = el('ul', 'submenu');
          parent.appendChild(sub);
          parent.classList.add('has-sub');
          var btn = el('button', 'sub-toggle');
          btn.type = 'button';
          btn.setAttribute('aria-expanded', 'false');
          btn.setAttribute('aria-label', 'Show more under ' + parent.querySelector('a').textContent);
          parent.insertBefore(btn, sub);
          (function (item, button) {  // capture this item: `parent` changes as the loop goes on
            button.addEventListener('click', function (e) {
              e.stopPropagation();
              var open = !item.classList.contains('sub-open');
              $all('.menu .has-sub.sub-open').forEach(function (o) { o.classList.remove('sub-open'); });
              if (open) item.classList.add('sub-open');
              button.setAttribute('aria-expanded', open ? 'true' : 'false');
            });
          })(parent, btn);
        }
        sub.appendChild(li);
      } else {
        a.textContent = label.replace(/^_+\s*/, '');
        parent = li;
      }
    });
    doc.addEventListener('click', function () {
      $all('.menu .has-sub.sub-open').forEach(function (o) { o.classList.remove('sub-open'); });
    });
    // Mark the current page in the menu
    var here = location.pathname + location.hash;
    $all('a', menu).forEach(function (a) {
      var url = a.getAttribute('href') || '';
      try { url = new URL(url, location.href); } catch (err) { return; }
      if (url.host === location.host && url.pathname + url.hash === here && url.pathname !== '/') a.classList.add('is-current');
    });
  }

  function setMenu(open) {
    if (!header || !toggle) return;
    header.classList.toggle('nav-open', open);
    root.classList.toggle('no-scroll', open);
    toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
    toggle.setAttribute('aria-label', open ? 'Close menu' : 'Open menu');
  }
  if (header && toggle && drawer) {
    toggle.addEventListener('click', function () { setMenu(!header.classList.contains('nav-open')); });
    drawer.addEventListener('click', function (e) {
      var t = e.target;
      while (t && t !== drawer) {
        if (t.tagName === 'A') { setMenu(false); return; }
        t = t.parentNode;
      }
    });
    doc.addEventListener('keydown', function (e) {
      if ((e.key === 'Escape' || e.key === 'Esc') && header.classList.contains('nav-open')) {
        setMenu(false);
        toggle.focus();
      }
    });
    if (desktop) {
      var onChange = function () { fitNav(); if (desktop.matches && !root.classList.contains('nav-collapse')) setMenu(false); };
      if (desktop.addEventListener) desktop.addEventListener('change', onChange);
      else if (desktop.addListener) desktop.addListener(onChange);
    }
  }

  // Wide screens show the menu in the header, but only if it fits next to the logo
  // (long menus or wide logos). Otherwise keep the hamburger, as on phones.
  function fitNav() {
    var inner = header && $('.header-inner', header);
    if (!inner) return;
    root.classList.remove('nav-collapse');
    if (!desktop || !desktop.matches) return;
    if (inner.scrollWidth > inner.clientWidth + 1) root.classList.add('nav-collapse');
    else if (header.classList.contains('nav-open')) setMenu(false);
  }
  fitNav();
  var fitTimer = null;
  window.addEventListener('resize', function () { clearTimeout(fitTimer); fitTimer = setTimeout(fitNav, 120); });
  if (doc.fonts && doc.fonts.ready) doc.fonts.ready.then(fitNav);
  var logo = $('.brand img');
  if (logo && !logo.complete) logo.addEventListener('load', fitNav);

  // Header shadow and back-to-top button
  var backTop = $('#back-to-top');
  var ticking = false;
  function onScroll() {
    if (ticking) return;
    ticking = true;
    window.requestAnimationFrame(function () {
      var y = window.pageYOffset || root.scrollTop;
      if (header) header.classList.toggle('is-scrolled', y > 8);
      if (backTop) backTop.classList.toggle('is-visible', y > 700);
      ticking = false;
    });
  }
  window.addEventListener('scroll', onScroll, { passive: true });
  onScroll();

  // ---------------------------------------------------------------- hero slider
  var hero = $('#home');
  var slides = $all('#main-slider > .widget');
  var pics = $all('#main-slider-images > .widget');
  var controls = $('#hero-controls');
  if (hero && slides.length && getComputedStyle(hero).display !== 'none') {
    var current = 0;
    var timer = null;
    var dots = [];
    var show = function (i) {
      current = (i + slides.length) % slides.length;
      slides.forEach(function (s, n) {
        s.classList.toggle('is-active', n === current);
        s.setAttribute('aria-hidden', n === current ? 'false' : 'true');
      });
      pics.forEach(function (p, n) { p.classList.toggle('is-active', pics.length && n === current % pics.length); });
      dots.forEach(function (d, n) {
        d.classList.remove('is-active');
        d.setAttribute('aria-current', n === current ? 'true' : 'false');
        if (n === current) { void d.offsetWidth; d.classList.add('is-active'); }
      });
    };
    var play = function () {
      if (reduceMotion || slides.length < 2) return;
      clearInterval(timer);
      timer = setInterval(function () { show(current + 1); }, 7000);
    };
    var pause = function () { clearInterval(timer); timer = null; };

    if (controls && slides.length > 1) {
      var prev = el('button', 'hero-arrow', '\u2039');
      prev.type = 'button';
      prev.setAttribute('aria-label', 'Previous slide');
      var next = el('button', 'hero-arrow', '\u203A');
      next.type = 'button';
      next.setAttribute('aria-label', 'Next slide');
      var dotWrap = el('div', 'hero-dots');
      slides.forEach(function (s, n) {
        var d = el('button', 'hero-dot');
        d.type = 'button';
        d.setAttribute('aria-label', 'Show slide ' + (n + 1));
        d.addEventListener('click', function () { show(n); play(); });
        dots.push(d);
        dotWrap.appendChild(d);
      });
      prev.addEventListener('click', function () { show(current - 1); play(); });
      next.addEventListener('click', function () { show(current + 1); play(); });
      controls.appendChild(prev);
      controls.appendChild(dotWrap);
      controls.appendChild(next);
    }
    hero.addEventListener('mouseenter', function () { hero.classList.add('is-paused'); pause(); });
    hero.addEventListener('mouseleave', function () { hero.classList.remove('is-paused'); play(); });
    hero.addEventListener('focusin', function () { hero.classList.add('is-paused'); pause(); });
    hero.addEventListener('focusout', function () { hero.classList.remove('is-paused'); play(); });
    doc.addEventListener('visibilitychange', function () { if (doc.hidden) pause(); else play(); });
    // Swipe on phones
    var startX = null;
    hero.addEventListener('touchstart', function (e) { startX = e.touches[0].clientX; }, { passive: true });
    hero.addEventListener('touchend', function (e) {
      if (startX === null) return;
      var dx = e.changedTouches[0].clientX - startX;
      if (Math.abs(dx) > 50) { show(current + (dx < 0 ? 1 : -1)); play(); }
      startX = null;
    });
    hero.classList.add('is-ready');
    show(0);
    play();
  }

  // ---------------------------------------------------------------- stories
  // Card excerpts: plain text from the post body (kept inert in a <template>)
  $all('template.js-excerpt').forEach(function (tpl) {
    var out = tpl.previousElementSibling;
    if (!out || !out.classList.contains('post-card-excerpt')) return;
    var holder = el('div');
    holder.appendChild(tpl.content ? tpl.content.cloneNode(true) : doc.createTextNode(tpl.textContent));
    $all('script, style, noscript, iframe, .separator', holder).forEach(function (n) { n.parentNode.removeChild(n); });
    var text = (holder.textContent || '').replace(/\s+/g, ' ').replace(/^\s+|\s+$/g, '');
    if (text.length > 150) text = text.slice(0, 150).replace(/\s+\S*$/, '') + '\u2026';
    out.textContent = text;
    tpl.parentNode.removeChild(tpl);
  });

  // Dates: "12 October 2026" style, whatever the blog's timestamp setting
  $all('time.js-date').forEach(function (t) {
    var when = new Date(t.getAttribute('datetime'));
    if (!isNaN(when.getTime())) {
      t.textContent = when.toLocaleDateString('en-GB', { year: 'numeric', month: 'long', day: 'numeric' });
    }
  });

  // Related stories from the post's first label (same-site JSON feed)
  var related = $('.related');
  var firstLabel = related && $('.related-label', related);
  if (related && firstLabel && window.fetch) {
    var label = firstLabel.getAttribute('data-label');
    var self = (related.getAttribute('data-url') || '').replace(/^https?:/, '');
    fetch('/feeds/posts/default/-/' + encodeURIComponent(label) + '?alt=json&max-results=6')
      .then(function (r) { return r.ok ? r.json() : null; })
      .then(function (data) {
        var entries = (data && data.feed && data.feed.entry) || [];
        var grid = $('.related-grid', related);
        var count = 0;
        entries.forEach(function (entry) {
          if (count >= 3) return;
          var link = (entry.link || []).filter(function (l) { return l.rel === 'alternate'; })[0];
          if (!link || link.href.replace(/^https?:/, '') === self) return;
          var card = el('a', 'related-card');
          card.href = link.href;
          var thumb = entry.media$thumbnail && entry.media$thumbnail.url;
          if (thumb) {
            var frame = el('span', 'fit-frame');
            var img = el('img');
            img.src = sized(thumb, 's600');
            img.alt = '';
            img.loading = 'lazy';
            frame.appendChild(img);
            card.appendChild(frame);
            fillFrame(frame);
          } else {
            card.appendChild(el('span', 'related-ph'));
          }
          card.appendChild(el('span', 'related-name', entry.title ? entry.title.$t : 'Story'));
          grid.appendChild(card);
          count++;
        });
        if (count) related.hidden = false;
      })
      .catch(function () { /* no related stories: section stays hidden */ });
  }

  // Copy-link share button
  $all('[data-copy-url]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var url = btn.getAttribute('data-copy-url');
      var label = btn.innerHTML;
      var done = function () {
        btn.textContent = 'Link copied';
        setTimeout(function () { btn.innerHTML = label; }, 1800);
      };
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(url).then(done, function () { window.prompt('Copy this link:', url); });
      } else {
        window.prompt('Copy this link:', url);
      }
    });
  });

  // ---------------------------------------------------------------- gallery lightbox
  var box = $('#lightbox');
  var links = $all('.gallery-link');
  if (box && links.length) {
    var big = $('.lightbox-img', box);
    var at = 0;
    var opener = null;
    var openAt = function (i) {
      at = (i + links.length) % links.length;
      var img = links[at].querySelector('img');
      big.src = sized(links[at].getAttribute('href'), 's1600');
      big.alt = img ? img.alt : '';
    };
    var close = function () {
      box.classList.remove('is-open');
      box.setAttribute('aria-hidden', 'true');
      root.classList.remove('no-scroll');
      if (opener) opener.focus();
    };
    links.forEach(function (a, i) {
      a.addEventListener('click', function (e) {
        e.preventDefault();
        opener = a;
        openAt(i);
        box.classList.add('is-open');
        box.setAttribute('aria-hidden', 'false');
        root.classList.add('no-scroll');
        $('.lightbox-close', box).focus();
      });
    });
    $('.lightbox-close', box).addEventListener('click', close);
    $('.lightbox-prev', box).addEventListener('click', function () { openAt(at - 1); });
    $('.lightbox-next', box).addEventListener('click', function () { openAt(at + 1); });
    box.addEventListener('click', function (e) { if (e.target === box) close(); });
    doc.addEventListener('keydown', function (e) {
      if (!box.classList.contains('is-open')) return;
      if (e.key === 'Escape' || e.key === 'Esc') close();
      else if (e.key === 'ArrowLeft') openAt(at - 1);
      else if (e.key === 'ArrowRight') openAt(at + 1);
    });
    if (links.length < 2) {
      $('.lightbox-prev', box).hidden = true;
      $('.lightbox-next', box).hidden = true;
    }
  }

  // ---------------------------------------------------------------- scroll reveal
  if ('IntersectionObserver' in window && !reduceMotion) {
    var targets = $all('.reveal, .card-grid > .widget, .gallery > .widget, .team-grid > .widget, .logo-grid > .widget, .post-grid > .post-card');
    targets.forEach(function (t) {
      t.classList.add('reveal');
      var i = Array.prototype.indexOf.call(t.parentNode.children, t);
      if (!t.classList.contains('section') && i > 0) t.style.transitionDelay = Math.min(i, 5) * 80 + 'ms';
    });
    root.classList.add('js-reveal');
    var io = new IntersectionObserver(function (items) {
      items.forEach(function (item) {
        if (item.isIntersecting) {
          item.target.classList.add('is-visible');
          io.unobserve(item.target);
        }
      });
    }, { rootMargin: '0px 0px -8% 0px' });
    targets.forEach(function (t) { io.observe(t); });
    window.addEventListener('beforeprint', function () { targets.forEach(function (t) { t.classList.add('is-visible'); }); });
  }

  // Footer year
  $all('.js-year').forEach(function (y) { y.textContent = String(new Date().getFullYear()); });
})();
//
